      "logo": "https://nomadsworld.com/favicon.svg",
      "telephone": "+611800666237",
      "email": "bookings@nomadsworld.com",
      "foundingDate": "1999",
      "address": {
        "@type": "PostalAddress",
        "streetAddress": "477 Kent St",
        "addressLocality": "Sydney",
        "addressRegion": "NSW",
        "postalCode": "2000",
        "addressCountry": "AU"
      },
      "sameAs": [
        "https://www.facebook.com/NomadsHostels/",
        "https://www.instagram.com/nomadshostels/",
        "https://twitter.com/nomadsworld"
      ]
    }
  ", "
    {
      "@context": "https://schema.org",
      "@type": "FAQPage",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "What is Nomads?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Nomads World is an Australian backpacker hostel network operating 15+ hostels across Australia, New Zealand and Thailand. We offer dorm beds, private rooms and the Bed Hopper multi-night accommodation pass for budget travellers and working holiday makers."
          }
        },
        {
          "@type": "Question",
          "name": "Where are Nomads hostels located?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Nomads has hostels across Australia (Sydney, Byron Bay, Noosa, Airlie Beach, Cairns, Magnetic Island, Coffs Harbour, St Kilda, Adelaide, Darwin), New Zealand (Wellington, Queenstown) and Thailand (Krabi/Ao Nang, Koh Tao)."
          }
        },
        {
          "@type": "Question",
          "name": "What is the Bed Hopper Pass?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "The Bed Hopper Pass is a pre-paid multi-night accommodation pass valid at all Nomads hostels across Australia, New Zealand and Thailand. Passes start from AUD $550 for 10 nights ($55/night) up to $2,845 for 60 nights. You book each stay directly with the hostel by quoting your card number with at least 48 hours notice."
          }
        },
        {
          "@type": "Question",
          "name": "Does Nomads World offer working holiday programmes?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. The Meet Me programme at select Nomads hostels is designed for working holiday visa holders. It includes your first week of accommodation, social activities and a local orientation to help you find work and settle in to a new city."
          }
        },
        {
          "@type": "Question",
          "name": "How do I book a Nomads hostel?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "You can book online directly via the booking widget on each hostel page at nomadsworld.com, or contact the hostel by email or phone. Nomads hostels are located across Australia, New Zealand and Thailand."
          }
        }
      ]
    }
  "]

