json_ld:
["{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "@id": "https://www.comparethemarket.com/#frequentlyaskedquestions",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How do comparison sites make money?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "We only make money when we’ve helped you with your new deal. For example, when you’ve found your new supplier or provider through us, our fee is paid by them. This fee doesn’t change the price you pay – we have no control over these prices and how they vary. So, to keep your life simple we always order them from lowest to highest. Find out more"
      }
    },
    {
      "@type": "Question",
      "name": "Can I trust your prices?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "You sure can, here’s why: We work with trusted providers to help you find some of the best prices The prices we show you aren’t affected by fees we get from providers We show you what suits your needs to help you make the right choice "
      }
    },
    {
      "@type": "Question",
      "name": "Shouldn’t I just buy direct from providers?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "We compare the market for you, letting you see prices and features side-by-side. We make it easy for you to compare prices from over  provider products[4] [4] "
      }
    },
    {
      "@type": "Question",
      "name": "Shouldn’t I try more than one comparison site?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "It's only natural to shop around for the best price. We'll remember all your details, so you can retrieve your quotes when you come back. Your time is valuable, so we make it as quick and easy as possible to get it all done with us. We like savvy shoppers. You're the ones our business is built for. But, we also know that everyone values their time as much as their money, so we've made sure every step of our comparison service is as quick and easy to use as possible. Not ready to buy just yet? We'll remember your quotes so they're here when you get back.  Find out more We reckon if you can get all shopping done under one roof, it’ll leave you with more time to get on with the other things you really enjoy doing. (Like enjoying a meal or going to the movies.)"
      }
    },
    {
      "@type": "Question",
      "name": "What are Rewards?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "It's our way of saying thanks when you take out a qualifying product through us. Meerkat Meals gives you great offers only through the Meerkat app. From dining out, with 25% off your total bill on varying days of the week, to 50% off pizzas from Domino’s, Papa Johns & Pizza Hut, 7 days a week. Order via the app then sit back and relax. Meerkat Movies gives you 2 for 1 cinema tickets every week on Tuesday or Wednesday to enjoy the latest and greatest films on the big screen. We’ve also teamed up with Caffè Nero to offer you 25% off barista-made drinks and freshly baked pastries – twice a day, every single day of the week. Only with the Meerkat app. T&Cs apply Find out more"
      }
    }
  ]
}", "[{"@id":"https://www.comparethemarket.com/","url":"https://www.comparethemarket.com/","logo":{"url":"https://cdn2.comparethemarket.com/market/cms/logos/ctm-logo-350x43px.png","@type":"ImageObject","width":{"@type":"QuantitativeValue","value":350,"unitCode":"E37","unitText":"pixel"},"height":{"@type":"QuantitativeValue","value":42,"unitCode":"E37","unitText":"pixel"}},"name":"Compare the Market","@type":"Organization","sameAs":["https://www.linkedin.com/company/comparethemarket-com/","https://twitter.com/comparethemkt","https://www.facebook.com/comparethemkt/","https://www.youtube.com/user/comparemarket","https://www.instagram.com/comparethemarket/"],"slogan":"Keep Life Simples","@context":"https://schema.org","contactPoint":[{"@type":"ContactPoint","email":"support@comparethemarket.com","contactType":"General enquiries"},{"@type":"ContactPoint","email":"marketing@comparethemarket.com","contactType":"Marketing enquiries"},{"@type":"ContactPoint","email":"commercial@comparethemarket.com","contactType":"Commercial opportunities"}]},{"url":"https://www.comparethemarket.com/","name":"Comparethemarket","@type":"WebSite","@context":"https://schema.org"}]"]

